            var sig = md.DecodeSignature(new SignatureTypeProvider(), null);
            Console.WriteLine($"  Return: {sig.ReturnType}");
            Console.WriteLine($"  Params: {string.Join(", ", sig.ParameterTypes)}");
            // Check generic constraints
            foreach (var gpHandle in md.GetGenericParameters()) {
                var gp = mdReader.GetGenericParameter(gpHandle);
                Console.WriteLine($"  GenericParam: {mdReader.GetString(gp.Name)}, Attrs: {gp.Attributes}");
                foreach (var gcHandle in gp.GetConstraints()) {
                    var gc = mdReader.GetGenericParameterConstraint(gcHandle);
                    Console.WriteLine($"    Constraint handle: {gc.Type.Kind}");
                    if (gc.Type.Kind == HandleKind.TypeReference) {
                        var tr = mdReader.GetTypeReference((TypeReferenceHandle)gc.Type);
                        Console.WriteLine($"    Constraint: {mdReader.GetString(tr.Namespace)}.{mdReader.GetString(tr.Name)}");
                    } else if (gc.Type.Kind == HandleKind.TypeSpecification) {
                        Console.WriteLine($"    Constraint: TypeSpec");
                    }
                }
            }
        }
    }
}

